def transform(grid):
    from collections import Counter
    H, W = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    rest = [c for c, _ in cnt.most_common() if c != bg]
    block_color = max(rest, key=lambda c: cnt[c]) if rest else None

    seen = [[False] * W for _ in range(H)]
    blocks = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] == block_color and not seen[i][j]:
                comp, st = [], [(i, j)]
                seen[i][j] = True
                while st:
                    r, c = st.pop(); comp.append((r, c))
                    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < H and 0 <= nc < W and not seen[nr][nc] and grid[nr][nc] == block_color:
                            seen[nr][nc] = True; st.append((nr, nc))
                blocks.append(comp)

    def info(comp):
        rs = [r for r, c in comp]; cs = [c for r, c in comp]
        return min(rs), max(rs), min(cs), max(cs)

    binfos = [info(b) for b in blocks]
    out = [row[:] for row in grid]

    for mr in range(H):
        for mc in range(W):
            if grid[mr][mc] in (bg, block_color):
                continue
            mcol = grid[mr][mc]
            cands = []
            for bi, (r0, r1, c0, c1) in enumerate(binfos):
                if r0 <= mr <= r1:
                    if mc > c1:
                        cands.append(('h', bi, -1, mc - c1))
                    elif mc < c0:
                        cands.append(('h', bi, 1, c0 - mc))
                if c0 <= mc <= c1:
                    if mr > r1:
                        cands.append(('v', bi, -1, mr - r1))
                    elif mr < r0:
                        cands.append(('v', bi, 1, r0 - mr))
            if not cands:
                continue
            cands.sort(key=lambda x: x[3])
            axis, bi, d, _ = cands[0]
            r0, r1, c0, c1 = binfos[bi]
            # fill from marker toward block
            if axis == 'h':
                r, c = mr, mc + d
                while 0 <= c < W and grid[r][c] != block_color:
                    if grid[r][c] == bg:
                        out[r][c] = mcol
                    c += d
                idx = mr - r0
            else:
                r, c = mr + d, mc
                while 0 <= r < H and grid[r][c] != block_color:
                    if grid[r][c] == bg:
                        out[r][c] = mcol
                    r += d
                idx = mc - c0
            out[mr][mc] = 4
            # emergent rays from all other blocks at same offset
            for bj, (s0, s1, t0, t1) in enumerate(binfos):
                if bj == bi:
                    continue
                if axis == 'h':
                    if s0 <= r0 + idx <= s1:
                        row = r0 + idx
                        c = (t1 + 1) if d == 1 else (t0 - 1)
                        while 0 <= c < W:
                            if grid[row][c] != block_color and grid[row][c] == bg:
                                out[row][c] = mcol
                            elif grid[row][c] == block_color:
                                break
                            c += d
                else:
                    if t0 <= c0 + idx <= t1:
                        col = c0 + idx
                        r = (s1 + 1) if d == 1 else (s0 - 1)
                        while 0 <= r < H:
                            if grid[r][col] != block_color and grid[r][col] == bg:
                                out[r][col] = mcol
                            elif grid[r][col] == block_color:
                                break
                            r += d
    return out
